import{_ as e,C as t,c as n,o as i,j as r,G as s,b as a,a0 as l,a as d,w as h,a1 as u}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Erstellung Ihres Trainingsplans","description":"","frontmatter":{},"headers":[],"relativePath":"de/education/goals/planning.md","filePath":"de/education/goals/planning.md"}');const o=e({name:"de/education/goals/planning.md"},[["render",function(e,g,o,c,b,p){const f=t("AdBanner"),m=t("Mermaid"),k=t("AdInArticle");return i(),n("div",null,[g[1]||(g[1]=r("h1",{id:"erstellung-ihres-trainingsplans",tabindex:"-1"},[d("Erstellung Ihres Trainingsplans "),r("a",{class:"header-anchor",href:"#erstellung-ihres-trainingsplans","aria-label":'Permalink to "Erstellung Ihres Trainingsplans"'},"​")],-1)),s(f),g[2]||(g[2]=r("p",null,"Ziele ohne Plan sind nur Wünsche. Dieser Leitfaden hilft Ihnen, Ihre Ziele in einen strukturierten Trainingsplan umzusetzen, der tatsächlich funktioniert.",-1)),g[3]||(g[3]=r("div",{class:"tip custom-block"},[r("p",{class:"custom-block-title"},"Die große Idee"),r("p",null,[r("strong",null,"Ziele ohne Plan sind nur Wünsche."),d(" Ein strukturierter Trainingsplan verwandelt Ihre Ziele in tägliche Handlungen, die sich zu echten Fortschritten summieren.")])],-1)),(i(),a(u,null,{default:h(()=>[s(m,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BZiel%5D%20--%3E%20B%5BTrainingsplan%5D%0A%20%20%20%20B%20--%3E%20C%5BT%C3%A4gliche%20Aktivit%C3%A4ten%5D%0A%20%20%20%20C%20--%3E%20D%5BKonsequente%20Praxis%5D%0A%20%20%20%20D%20--%3E%20E%5BMessbarer%20Fortschritt%5D%0A%20%20%20%20E%20--%3E%20F%5BZielerreichung%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23e8f5e9%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:h(()=>[...g[0]||(g[0]=[d(" Loading... ",-1)])]),_:1})),g[4]||(g[4]=l('<h2 id="die-8-phasen-der-selbstgesteuerten-entwicklung" tabindex="-1">Die 8 Phasen der selbstgesteuerten Entwicklung <a class="header-anchor" href="#die-8-phasen-der-selbstgesteuerten-entwicklung" aria-label="Permalink to &quot;Die 8 Phasen der selbstgesteuerten Entwicklung&quot;">​</a></h2><h3 id="phase-1-setzen-sie-sich-ihre-ziele" tabindex="-1">Phase 1: Setzen Sie sich Ihre Ziele <a class="header-anchor" href="#phase-1-setzen-sie-sich-ihre-ziele" aria-label="Permalink to &quot;Phase 1: Setzen Sie sich Ihre Ziele&quot;">​</a></h3><p>Sie haben bereits etwas über SMART-Ziele gelernt. Ordnen Sie diese nun nach ihrer Bedeutung:</p><ol><li><strong>Langfristiges Ziel</strong> (1-2 Jahre): Ihr Traum</li><li><strong>Jahresziel</strong>: Zielvorgabe für dieses Jahr</li><li><strong>Quartalsziele</strong>: Meilensteine nach 3 Monaten</li><li><strong>Monatliche Ziele</strong>: Spezifische Schwerpunkte</li><li><strong>Wöchentliche Ziele</strong>: Trainingsziele</li></ol><h3 id="phase-2-schatzen-sie-ihre-ressourcen-ein" tabindex="-1">Phase 2: Schätzen Sie Ihre Ressourcen ein <a class="header-anchor" href="#phase-2-schatzen-sie-ihre-ressourcen-ein" aria-label="Permalink to &quot;Phase 2: Schätzen Sie Ihre Ressourcen ein&quot;">​</a></h3><p>Bevor Sie mit der Planung beginnen, sollten Sie ehrlich prüfen, was Sie haben:</p><table tabindex="0"><thead><tr><th>Ressource</th><th>Fragen, die man stellen sollte</th></tr></thead><tbody><tr><td><strong>Zeit</strong></td><td>Wie viele Stunden pro Woche können Sie realistisch trainieren?</td></tr><tr><td><strong>Standort</strong></td><td>Haben Sie Zugang zu einer geeigneten Piste? Wie ist die Oberflächenbeschaffenheit?</td></tr><tr><td><strong>Ausrüstung</strong></td><td>Haben Sie geeignete Kugeln? Messwerkzeuge? Videoausrüstung?</td></tr><tr><td><strong>Wissen</strong></td><td>Was sind Ihre technischen Stärken und Schwächen?</td></tr><tr><td><strong>Körperlicher Zustand</strong></td><td>Gibt es Einschränkungen? Bereiche, in denen Verbesserungsbedarf besteht?</td></tr></tbody></table><p>Seien Sie ehrlich. Ein realistischer Plan ist besser als eine ambitionierte Fantasie.</p><h3 id="phase-3-wahle-deine-ubungen" tabindex="-1">Phase 3: Wähle deine Übungen <a class="header-anchor" href="#phase-3-wahle-deine-ubungen" aria-label="Permalink to &quot;Phase 3: Wähle deine Übungen&quot;">​</a></h3><p>Wählen Sie Übungen, die Ihre Ziele direkt unterstützen:</p><p><strong>Zur Verbesserung der Zeigerfunktion:</strong></p><ul><li>Präzises Zeigen auf markierte Zonen</li><li>Übungen zur Distanzvariation</li><li>Verschiedene Oberflächenpraktiken</li></ul><p><strong>Zur Verbesserung der Treffsicherheit:</strong></p><ul><li>Schießleiter (progressive Distanzen)</li><li>Hindernisschießen (erzwungener hoher Bogen)</li><li>Übung mit beweglichen Zielen</li></ul><p><strong>Zur geistigen Entwicklung:</strong></p><ul><li>Routineübungen vor dem Schuss</li><li>Visualisierungssitzungen</li><li>Drucksimulation</li></ul><p><strong>Gestalten Sie Ihr Programm aus:</strong></p><ul><li>Technische Arbeiten (Zeigen, Schießen)</li><li>Mentales Training (Achtsamkeit, Visualisierung)</li><li>Körperliche Kondition (Gleichgewicht, Flexibilität)</li><li>Spielpraxis (Anwendung von Fähigkeiten)</li></ul><h3 id="phase-4-erstellen-sie-ihren-zeitplan" tabindex="-1">Phase 4: Erstellen Sie Ihren Zeitplan <a class="header-anchor" href="#phase-4-erstellen-sie-ihren-zeitplan" aria-label="Permalink to &quot;Phase 4: Erstellen Sie Ihren Zeitplan&quot;">​</a></h3><p>Erstellen Sie einen realistischen Wochenplan:</p>',20)),s(k),g[5]||(g[5]=l('<table tabindex="0"><thead><tr><th>Tag</th><th>Morgen</th><th>Nachmittag</th><th>Abend</th><th>Fokus</th></tr></thead><tbody><tr><td>Montag</td><td>-</td><td>Technisch: Zeigen</td><td>Leichte Mobilität</td><td>Präzision</td></tr><tr><td>Di.</td><td>-</td><td>Technik: Aufnahmen</td><td>-</td><td>Leistung/Genauigkeit</td></tr><tr><td>Heiraten</td><td>-</td><td>Mentales Training</td><td>-</td><td>Achtsamkeit</td></tr><tr><td>Donnerstag</td><td>-</td><td>Gemischt: Spielszenarien</td><td>Leichte Mobilität</td><td>Anwendung</td></tr><tr><td>Freitag</td><td>-</td><td>Technische Schwäche</td><td>-</td><td>Verbesserung</td></tr><tr><td>Sa</td><td>Spiel oder Wettkampf</td><td>-</td><td>-</td><td>Leistung</td></tr><tr><td>Sonne</td><td>Ausruhen</td><td>Wochenrückblick</td><td>Planung</td><td>Erholung</td></tr></tbody></table><p><strong>Grundprinzipien:</strong></p><ul><li>Mentales Training sollte Priorität haben (es wird oft vernachlässigt).</li><li>Ruhetage einschließen</li><li>Unterschiedliche Fähigkeiten ausbalancieren</li><li>Flexibilität fürs Leben</li></ul><h3 id="phase-5-vorbereitung-auf-hindernisse" tabindex="-1">Phase 5: Vorbereitung auf Hindernisse <a class="header-anchor" href="#phase-5-vorbereitung-auf-hindernisse" aria-label="Permalink to &quot;Phase 5: Vorbereitung auf Hindernisse&quot;">​</a></h3><p>Es wird etwas schiefgehen. Planen Sie dafür ein.</p><table tabindex="0"><thead><tr><th>Risiko</th><th>Wahrscheinlichkeit</th><th>Auswirkungen</th><th>Backup-Plan</th></tr></thead><tbody><tr><td>Zeitmangel</td><td>Hoch</td><td>Medium</td><td>Halten Sie eine „Minimalsitzung“ (20 Minuten) bereit.</td></tr><tr><td>Schlechtes Wetter</td><td>Medium</td><td>Medium</td><td>Innenraumvisualisierung, Videostudie</td></tr><tr><td>Geringe Motivation</td><td>Hoch</td><td>Medium</td><td>Zurück zum „Warum“, kleinere Ziele setzen, eine Pause einlegen</td></tr><tr><td>Leichte Verletzung</td><td>Medium</td><td>Hoch</td><td>Fokus auf mentales Training, nicht beeinträchtigte Fähigkeiten</td></tr><tr><td>Kein Übungspartner</td><td>Medium</td><td>Niedrig</td><td>Solo-Übungen, Video-Selbstanalyse</td></tr></tbody></table><h3 id="phase-6-verfolge-deinen-fortschritt" tabindex="-1">Phase 6: Verfolge deinen Fortschritt <a class="header-anchor" href="#phase-6-verfolge-deinen-fortschritt" aria-label="Permalink to &quot;Phase 6: Verfolge deinen Fortschritt&quot;">​</a></h3><p>Was gemessen wird, wird auch gesteuert.</p><p><strong>Führe ein Trainingstagebuch:</strong></p><ul><li>Datum und Dauer</li><li>Übungen abgeschlossen</li><li>Ergebnisse</li><li>Wie Sie sich gefühlt haben (Energie, Konzentration, Flow)</li><li>Technische Hinweise</li><li>Wetter/Bedingungen</li></ul><p><strong>Wöchentliche Wiederholungsfragen:</strong></p><ul><li>Habe ich meine geplanten Sitzungen absolviert?</li><li>Welche Punktzahl habe ich erreicht?</li><li>Was hat sich gut angefühlt? Was war schwierig?</li><li>Irgendwelche Flow-Erlebnisse?</li><li>Was sollte ich anpassen?</li></ul><h3 id="phase-7-motiviert-bleiben" tabindex="-1">Phase 7: Motiviert bleiben <a class="header-anchor" href="#phase-7-motiviert-bleiben" aria-label="Permalink to &quot;Phase 7: Motiviert bleiben&quot;">​</a></h3><p>Motivation schwankt. Entwickeln Sie Systeme, um sie aufrechtzuerhalten:</p><p><strong>Innere Motivation:</strong></p><ul><li>Verbinde dich mit deinem „Warum“</li><li>Feiere kleine Erfolge</li><li>Im Laufe der Zeit ist eine Verbesserung festzustellen.</li><li>Finde Freude am Prozess</li></ul><p><strong>Externe Unterstützung:</strong></p><ul><li>Trainingspartner (auch gelegentlich)</li><li>Ziele mit jemandem teilen</li><li>Treten Sie Online-Communities bei.</li><li>Serien und Konstanz verfolgen</li></ul><p><strong>Wenn die Motivation nachlässt:</strong></p><ul><li>Mach eine Minimalsitzung (besser etwas als nichts).</li><li>Verändern Sie Ihre Umgebung</li><li>Überprüfen Sie Ihren Fortschritt</li><li>Erinnern Sie sich an vergangene Erfolge</li><li>Machen Sie bei Bedarf eine geplante Pause.</li></ul><h3 id="phase-8-uberprufung-und-anpassung" tabindex="-1">Phase 8: Überprüfung und Anpassung <a class="header-anchor" href="#phase-8-uberprufung-und-anpassung" aria-label="Permalink to &quot;Phase 8: Überprüfung und Anpassung&quot;">​</a></h3><p>Ihr Plan sollte sich weiterentwickeln:</p><p><strong>Wöchentlich:</strong> Kurze Überprüfung, kleinere Anpassungen <strong>Monatlich:</strong> Fortschritte bei der Erreichung der Monatsziele bewerten, Fokus anpassen <strong>Vierteljährlich:</strong> Umfassende Überprüfung, Festlegung der Ziele für das nächste Quartal. <strong>Jährlich:</strong> Vollständige Bewertung, neuer Jahresplan</p><p><strong>Fragen zur Überprüfung:</strong></p><ul><li>Mache ich Fortschritte bei der Erreichung meiner Ziele?</li><li>Ist mein Training effektiv?</li><li>Benötige ich andere Übungen?</li><li>Sind meine Ziele noch relevant?</li><li>Was habe ich gelernt?</li></ul><h2 id="beispielhafter-8-wochen-plan" tabindex="-1">Beispielhafter 8-Wochen-Plan <a class="header-anchor" href="#beispielhafter-8-wochen-plan" aria-label="Permalink to &quot;Beispielhafter 8-Wochen-Plan&quot;">​</a></h2><p><strong>Ziel:</strong> Verbesserung der Schussgenauigkeit um 15 %</p><table tabindex="0"><thead><tr><th>Woche</th><th>Fokus</th><th>Wichtige Sitzungen</th></tr></thead><tbody><tr><td>1</td><td>Ausgangswert</td><td>Aktuelles Niveau prüfen, Videoanalyse</td></tr><tr><td>2</td><td>Technik</td><td>Identifizieren und bearbeiten Sie die wichtigsten Probleme</td></tr><tr><td>3</td><td>Wiederholung</td><td>Schießtraining mit hohem Volumen</td></tr><tr><td>4</td><td>Prüfen</td><td>Zwischenbewertung, Anpassung</td></tr><tr><td>5</td><td>Variation</td><td>Unterschiedliche Entfernungen und Winkel</td></tr><tr><td>6</td><td>Druck</td><td>Füge Übungen Konsequenzen hinzu</td></tr><tr><td>7</td><td>Integration</td><td>Spielähnliche Szenarien</td></tr><tr><td>8</td><td>Abschlussprüfung</td><td>Verbesserung messen</td></tr></tbody></table><h2 id="wichtigste-erkenntnis" tabindex="-1">Wichtigste Erkenntnis <a class="header-anchor" href="#wichtigste-erkenntnis" aria-label="Permalink to &quot;Wichtigste Erkenntnis&quot;">​</a></h2><blockquote><p>Plane deine Arbeit und setze deinen Plan dann um. Sei aber bereit, dich anzupassen.</p></blockquote><p>Der beste Plan ist der, den man auch wirklich befolgt. Fang einfach an, bleib konsequent und passe ihn an, während du dazulernst.</p>',31)),s(f)])}]]);export{g as __pageData,o as default};
